using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Security.AccessControl;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using Microsoft.Win32.SafeHandles;
namespace ClearSpace {
public sealed class RecoveryEntry {public string Format="ClearSpace.FileRecovery.v1",Computer,UserSid,Original,Stored,Hash,ApprovedRoot;public long Bytes,Modified;}
public sealed class RecoverySession {
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool DuplicateHandle(IntPtr sourceProcess,SafeFileHandle source,IntPtr targetProcess,out SafeFileHandle target,uint access,bool inherit,uint options);
 public string DirectoryPath,Manifest;public int Files;
 bool faulted;
 public RecoverySession(string root){if(String.IsNullOrEmpty(root))throw new IOException("请设置文件备份目录");DirectoryPath=Path.Combine(Path.GetFullPath(root),DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(DirectoryPath);if(!Engine.SafeAncestors(Path.Combine(DirectoryPath,"probe")))throw new IOException("备份路径包含链接");var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WindowsIdentity.GetCurrent().User,new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null),new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null)})acl.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(DirectoryPath,acl);Manifest=Path.Combine(DirectoryPath,"files.csbackup");}
 public void Save(SafeFileHandle handle,Rule rule,Snapshot snapshot,CancellationToken token){
  if(faulted)throw new IOException("本批备份索引写入失败，保留后续文件");if(rule.Roots.Any(r=>DirectoryPath.StartsWith(Engine.Normalize(r)+"\\",StringComparison.OrdinalIgnoreCase)))throw new IOException("备份目录不能位于清理目录内");string stored=Guid.NewGuid().ToString("N")+".bin",file=Path.Combine(DirectoryPath,stored);string hash;
  try{SafeFileHandle copy;if(!DuplicateHandle(new IntPtr(-1),handle,new IntPtr(-1),out copy,0,false,2))throw new IOException("无法安全读取备份内容");
   using(copy)using(var source=new FileStream(copy,FileAccess.Read,65536,false))using(var target=new FileStream(file,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var sha=SHA256.Create()){byte[] buffer=new byte[65536];int count;long bytes=0;while((count=source.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();target.Write(buffer,0,count);sha.TransformBlock(buffer,0,count,null,0);bytes+=count;}sha.TransformFinalBlock(new byte[0],0,0);target.Flush(true);if(bytes!=snapshot.Bytes)throw new IOException("备份大小变化");hash=BitConverter.ToString(sha.Hash).Replace("-","");}
   token.ThrowIfCancellationRequested();var entry=new RecoveryEntry{Computer=Environment.MachineName,UserSid=WindowsIdentity.GetCurrent().User.Value,Original=snapshot.Path,Stored=stored,Hash=hash,Bytes=snapshot.Bytes,Modified=snapshot.Modified,ApprovedRoot=rule.Roots.First(r=>rule.Single?Engine.Normalize(r)==Engine.Normalize(snapshot.Path):snapshot.Path.StartsWith(Engine.Normalize(r)+"\\",StringComparison.OrdinalIgnoreCase))};string json=new JavaScriptSerializer().Serialize(entry);byte[] sealedData=ProtectedData.Protect(Encoding.UTF8.GetBytes(json),null,DataProtectionScope.CurrentUser);using(var stream=new FileStream(Manifest,FileMode.Append,FileAccess.Write,FileShare.Read)){long previousLength=stream.Length;try{byte[] data=Encoding.UTF8.GetBytes(Convert.ToBase64String(sealedData)+"\n");if(stream.Length+data.Length>64L*1024*1024)throw new IOException("本批备份索引已达上限，请保留后续文件");stream.Write(data,0,data.Length);stream.Flush(true);}catch{faulted=true;try{stream.SetLength(previousLength);stream.Flush(true);}catch{}throw;}}Files++;
  }catch{try{if(File.Exists(file)&&Engine.SafeAncestors(file)&&(File.GetAttributes(file)&FileAttributes.ReparsePoint)==0)File.Delete(file);}catch{}throw;}
 }
}
public static class FileRecovery {
 public static string DefaultDirectory(){try{var disk=DriveInfo.GetDrives().FirstOrDefault(d=>d.IsReady&&d.DriveType==DriveType.Fixed&&!d.Name.Equals(RuleBook.TargetDrive,StringComparison.OrdinalIgnoreCase)&&d.AvailableFreeSpace>512L*1024*1024);if(disk!=null)return Path.Combine(disk.Name,"ClearSpaceBackups");}catch{}return Path.Combine(CleanerSettings.Root,"FileBackups");}
 public static List<RecoveryEntry> Read(string manifest){if(!Engine.SafeAncestors(manifest)||(File.GetAttributes(manifest)&FileAttributes.ReparsePoint)!=0||new FileInfo(manifest).Length>64L*1024*1024)throw new InvalidDataException("备份索引无效");string raw=File.ReadAllText(manifest);string[] lines=raw.Split('\n');var entries=new List<RecoveryEntry>();for(int i=0;i<lines.Length;i++){string line=lines[i].Trim();if(line.Length==0)continue;byte[] data;try{data=ProtectedData.Unprotect(Convert.FromBase64String(line),null,DataProtectionScope.CurrentUser);}catch{if(i==lines.Length-1&&!raw.EndsWith("\n")&&entries.Count>0)break;throw;}var e=new JavaScriptSerializer().Deserialize<RecoveryEntry>(Encoding.UTF8.GetString(data));if(e==null||e.Format!="ClearSpace.FileRecovery.v1"||e.Computer!=Environment.MachineName||e.UserSid!=WindowsIdentity.GetCurrent().User.Value||e.Stored==null||!System.Text.RegularExpressions.Regex.IsMatch(e.Stored,"^[0-9a-f]{32}\\.bin$")||e.Bytes<0||String.IsNullOrEmpty(e.Hash)||!Path.IsPathRooted(e.Original)||e.Original.StartsWith("\\\\"))throw new InvalidDataException("备份只能用于本机、本账户");string full=Engine.Normalize(e.Original),root=Engine.Normalize(e.ApprovedRoot);if(full!=root&&!full.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("备份范围校验失败");entries.Add(e);if(entries.Count>100000)throw new InvalidDataException("索引过大");}return entries;}
 public static int Restore(string manifest){var entries=Read(manifest);string root=Path.GetDirectoryName(Path.GetFullPath(manifest));int count=0;foreach(var e in entries){if(File.Exists(e.Original)||Directory.Exists(e.Original))continue;string stored=Path.Combine(root,e.Stored);if(!Engine.SafeAncestors(stored)||(File.GetAttributes(stored)&FileAttributes.ReparsePoint)!=0)throw new IOException("备份文件包含链接");using(var source=new FileStream(stored,FileMode.Open,FileAccess.Read,FileShare.Read)){using(var sha=SHA256.Create()){if(source.Length!=e.Bytes||BitConverter.ToString(sha.ComputeHash(source)).Replace("-","")!=e.Hash)throw new IOException("备份文件校验失败，未恢复");}source.Position=0;string parent=Path.GetDirectoryName(e.Original),existing=parent;while(!Directory.Exists(existing)){existing=Path.GetDirectoryName(existing);if(String.IsNullOrEmpty(existing))throw new IOException("原磁盘不可用");}if(!Engine.SafeAncestors(Path.Combine(existing,"probe")))throw new IOException("恢复位置包含链接");Directory.CreateDirectory(parent);if(!Engine.SafeAncestors(e.Original))throw new IOException("恢复位置包含链接");using(var target=new FileStream(e.Original,FileMode.CreateNew,FileAccess.Write,FileShare.None)){if(!String.Equals(Engine.Normalize(Native.FinalPath(target.SafeFileHandle)),Engine.Normalize(e.Original),StringComparison.OrdinalIgnoreCase))throw new IOException("恢复位置发生变化");source.CopyTo(target);target.Flush(true);}File.SetLastWriteTimeUtc(e.Original,DateTime.FromFileTimeUtc(e.Modified));count++;}}return count;}
 public static void Purge(string manifest){var entries=Read(manifest);string root=Path.GetDirectoryName(Path.GetFullPath(manifest));var files=entries.Select(e=>Path.Combine(root,e.Stored)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();foreach(string file in files){if(!File.Exists(file))continue;if(!Engine.SafeAncestors(file)||(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("备份位置包含链接");}foreach(string file in files)if(File.Exists(file))File.Delete(file);File.Delete(manifest);}
}
}
